use strict; use warnings;
my $REPO = "/bench/repo";

sub is_data_layer {
    my ($path) = @_;
    my $rel = $path;
    $rel =~ s/^\Q$REPO\E\/?//;
    return 1 if $rel =~ /^store\// || $rel eq "store";
    return 1 if $rel =~ /^proto\/gen\/store\//;
    return 0;
}

my @entities = qw(Attachment Memo MemoRelation InstanceSetting User UserSetting IdentityProvider Inbox Reaction MemoShare UserIdentity);
my %refs; $refs{$_} = {} for @entities;

opendir(my $dh, $REPO) or die $!;
my @files;
sub walk {
    my ($dir) = @_;
    opendir(my $d, $dir) or return;
    while (my $e = readdir $d) {
        next if $e eq "." || $e eq ".." || $e eq ".git";
        my $p = "$dir/$e";
        if (-d $p) { walk($p) }
        elsif ($p =~ /\.go$/) { push @files, $p }
    }
}
walk($REPO);

for my $path (@files) {
    next if is_data_layer($path);
    open my $fh, "<", $path or next;
    local $/; my $content = <$fh>; close $fh;
    next unless $content =~ /github\.com\/usememos\/memos\/store"/;
    (my $pkg = $path) =~ s/^\Q$REPO\E\/?//;
    $pkg =~ s/\/[^\/]+$//;
    for my $t (@entities) {
        if ($content =~ /\bstore\.$t\b/) {
            $refs{$t}{$pkg} = 1;
        }
    }
}

print "Rankings:\n";
my @ranked = sort { scalar(keys %{$refs{$b}}) <=> scalar(keys %{$refs{$a}}) } @entities;
for my $t (@ranked) {
    my @pkgs = sort keys %{$refs{$t}};
    print "$t: ", scalar(@pkgs), "\n";
    for (@pkgs) { print "  - $_\n" }
}
'

